function getLocation(){navigator.geolocation?navigator.geolocation.getCurrentPosition(showPosition):msg="Geolocation is not supported by this browser."}function showPosition(o){longitude=o.coords.longitude,latitude=o.coords.latitude}$(document).ready(function(o){var t="",n="";getLocation(),$.ajax({type:"POST",dataType:"json",data:{url:window.location.pathname+window.location.search,type:"analytics",action:"record",longitude:t,latitude:n},error:function(o){console.log(o)}})});